export function formatPythonBytes(bytes) {
  let rendered = "b'";

  for (const byte of bytes) {
    if (byte === 0x27) {
      rendered += "\\'";
    } else if (byte === 0x5c) {
      rendered += '\\\\';
    } else if (byte === 0x09) {
      rendered += '\\t';
    } else if (byte === 0x0a) {
      rendered += '\\n';
    } else if (byte === 0x0d) {
      rendered += '\\r';
    } else if (byte >= 0x20 && byte <= 0x7e) {
      rendered += String.fromCharCode(byte);
    } else {
      rendered += `\\x${toHex(byte)}`;
    }
  }

  rendered += "'";
  return rendered;
}

